INSERT [dbo].[TicketVoiding_MessageTemplate] ([TemplateId], [MsgEnglish], [MsgChineseTraditional], [MsgChineseSimplified], [MsgChineseNewSimplified], [JsonValue], [CreatedDate], [ModifiedDate], [Creator], [LastModifiedBy]) VALUES (1, N'Attn:[{{Sport type}}] Due to bets erroneously accepted in goal danger play during the match between "{{Home team name}} -vs- {{Away team name}}" [{{League name}} - {{Event Date}}{{Event type}}], bet ID: "@@" {{PlacedFromTimeRange}}{{Score}}are considered VOID. Parlay counted as (1). {{CheckStatement}}Sorry for the inconvenience caused!', N'請注意:[{{Sport type}}] 由於注單在有進球的危險時段中誤被接受, "{{Home team name}} -vs- {{Away team name}}" [{{League name}} - {{Event Date}}{{Event type}}], 注單: "@@" {{PlacedFromTimeRange}}{{Score}}已被作廢. 過關以(1)計算. {{CheckStatement}}不便之處 敬請見諒!', N'请注意:[{{Sport type}}] 由于注单在有进球的危险时段中误被接受, "{{Home team name}} -vs- {{Away team name}}" [{{League name}} - {{Event Date}}{{Event type}}], 注单: "@@" {{PlacedFromTimeRange}}{{Score}}已被作废. 过关以(1)计算. {{CheckStatement}}不便之处 敬请见谅!', N'请注意:[{{Sport type}}] 由于注单在有进球的危险时段中误被接受, "{{Home team name}} -vs- {{Away team name}}" [{{League name}} - {{Event Date}}{{Event type}}], 注单: "@@" {{PlacedFromTimeRange}}{{Score}}已被作废. 过关以(1)计算. {{CheckStatement}}不便之处 敬请见谅!', N'', NULL, NULL, NULL, NULL)
